def special_parity_subarrays(nums,queries):
    bad=[0]*len(nums)
    for index in range(1,len(nums)):bad[index]=bad[index-1]+((nums[index]&1)==(nums[index-1]&1))
    return [bad[right]==bad[left] for left,right in queries]

